def is_valid_sudoku(board):
    for i in range(9):
        row = set()
        col = set()
        box = set()
        for j in range(9):
            if board[i][j] != 0:
                if board[i][j] in row: return False
                row.add(board[i][j])
            if board[j][i] != 0:
                if board[j][i] in col: return False
                col.add(board[j][i])
            r, c = 3 * (i // 3), 3 * (i % 3)
            val = board[r + j // 3][c + j % 3]
            if val != 0:
                if val in box: return False
                box.add(val)
    return True
